const body = $input.first().json.body;
const query = body.query || '';

// Split on last '/' to get bom_material and process
const lastSlash = query.lastIndexOf('/');
let bom_material, process;
if (lastSlash > 0) {
  bom_material = query.substring(0, lastSlash).trim();
  process = query.substring(lastSlash + 1).trim();
} else {
  bom_material = query.trim();
  process = '';
}

return [{
  json: {
    query,
    bom_material,
    process,
    max_sites: body.max_sites ?? 7,
    num_results: body.num_results ?? 20,
    content_char_limit: body.content_char_limit ?? 800,
    raw_content_limit: body.raw_content_limit ?? 5000,
    profiling_temperature: body.profiling_temperature ?? 0.3,
    profiling_max_tokens: body.profiling_max_tokens ?? 1800,
    ranking_prompt: body.ranking_prompt ?? null,
    ranking_temperature: body.ranking_temperature ?? 0,
    ranking_max_tokens: body.ranking_max_tokens ?? 4000,
    ranking_sample_size: body.ranking_sample_size ?? 20,
    max_token_candidates: body.max_token_candidates ?? 20,
    relevance_weight_core: body.relevance_weight_core ?? 0.7,
    model: body.model ?? 'meta-llama/llama-4-maverick-17b-128e-instruct',
    start_time: Date.now()
  }
}];

