// Candidate Matching
// Extracts entity profile, looks up candidate terms from session DB (STUB),
// and formats candidate list for LLM Ranking.

const llmOutput = $input.first().json;
const params = $('Parse Query & Extract Params').first().json;
const braveResults = $('Brave Search').first().json;
const webResults = braveResults.web?.results || [];
const staticData = $getWorkflowStaticData('global');

// Extract entity profile from chainLlm output
const entity_profile = llmOutput.output || llmOutput;

// Match candidates from session term DB (STUB)
// TODO: implement inverted token index + overlap scoring
const terms = staticData.terms || [];
let token_matches;
if (terms.length > 0) {
  token_matches = terms
    .slice(0, Math.min(params.max_token_candidates, terms.length))
    .map((term, i) => [term, Math.round((0.85 - i * 0.05) * 100) / 100]);
} else {
  token_matches = [
    ['Placeholder Term 1', 0.85],
    ['Placeholder Term 2', 0.72],
    ['Placeholder Term 3', 0.65],
    ['Placeholder Term 4', 0.58],
    ['Placeholder Term 5', 0.50]
  ];
}

// Format candidates for LLM Ranking prompt
const candidate_lines = token_matches
  .slice(0, params.ranking_sample_size)
  .map(([term, score], i) => `${i + 1}. ${term}`)
  .join('\n');

return [{
  json: {
    ...params,
    entity_profile,
    core_concept: entity_profile.core_concept || '',
    entity_profile_json: JSON.stringify(entity_profile, null, 2),
    profiling_model: params.model,
    web_results_count: webResults.length,
    web_search_status: webResults.length > 0 ? 'success' : 'no_results',
    token_matches,
    candidate_lines
  }
}];

const llmOutput = $input.first().json;
const prev = $('Candidate Matching').first().json;

// chainLlm with outputParser wraps in .output
const rankingResult = llmOutput.output || llmOutput;
const ranked_items = rankingResult.ranked_items || [];

const elapsed = ((Date.now() - prev.start_time) / 1000).toFixed(1);

return [{
  json: {
    status: 'success',
    message: `Research completed - Found ${ranked_items.length} matches in ${elapsed}s`,
    data: {
      ranked_items,
      entity_profile: prev.entity_profile,
      token_matches: prev.token_matches,
      llm_provider: `groq/${prev.model}`,
      total_time: parseFloat(elapsed),
      web_search_status: prev.web_search_status,
      web_search_error: null,
      pipeline_steps: {
        cache_lookup: { hit: prev.cache_hit },
        fuzzy_matching: { hit: prev.fuzzy_hit, score: prev.fuzzy_score },
        web_search: { results_count: prev.web_results_count },
        entity_profiling: { model: prev.profiling_model },
        token_matching: { candidates_count: prev.token_matches.length },
        llm_ranking: { model: prev.model, candidates_count: ranked_items.length }
      }
    }
  }
}];
